export const LLMS_AR_PRE = "# \u0635\u0648\u062a \u0646\u062c\u062f\u064a (Saut Najdi)\n\n> \u0635\u0648\u062a \u0646\u062c\u062f\u064a \u0648\u0643\u064a\u0644 \u0635\u0648\u062a\u064a \u0633\u0639\u0648\u062f\u064a \u0628\u0627\u0644\u0630\u0643\u0627\u0621 \u0627\u0644\u0627\u0635\u0637\u0646\u0627\u0639\u064a \u064a\u0631\u062f \u0639\u0644\u0649 \u0639\u0645\u0644\u0627\u0626\u0643 \u0628\u0627\u0644\u0644\u0647\u062c\u0629 \u0627\u0644\u0644\u064a \u064a\u0641\u0647\u0645\u0648\u0646\u0647\u0627 \u2014 \u0646\u062c\u062f\u064a\u060c \u062d\u062c\u0627\u0632\u064a\u060c \u0634\u0627\u0645\u064a\u060c \u0628\u0627\u0644\u0639\u0631\u0628\u064a\u0629 \u0623\u0648 \u0627\u0644\u0625\u0646\u062c\u0644\u064a\u0632\u064a\u0629 \u2014 \u0648\u0645\u0648\u0638\u0641\u0643 \u0627\u0644\u0628\u0634\u0631\u064a \u064a\u0633\u062a\u0644\u0645 \u0627\u0644\u0645\u0643\u0627\u0644\u0645\u0629 \u0628\u0643\u0627\u0645\u0644 \u0633\u064a\u0627\u0642\u0647\u0627 \u0641\u064a \u0623\u064a \u0644\u062d\u0638\u0629.\n\n\u0635\u0648\u062a \u0646\u062c\u062f\u064a \u0645\u0646\u0635\u0629 \u0647\u062c\u064a\u0646\u0629 \u2014 \u0630\u0643\u0627\u0621 \u0627\u0635\u0637\u0646\u0627\u0639\u064a \u0648\u0628\u0634\u0631 \u2014 \u0644\u0644\u0645\u0643\u0627\u0644\u0645\u0627\u062a \u0648\u0627\u0644\u0645\u062d\u0627\u062f\u062b\u0627\u062a \u0627\u0644\u0648\u0627\u0631\u062f\u0629 \u0641\u064a \u0627\u0644\u0633\u0639\u0648\u062f\u064a\u0629. \u064a\u0631\u062f \u0639\u0644\u0649 \u0645\u0643\u0627\u0644\u0645\u0627\u062a \u0639\u0645\u0644\u0627\u0626\u0643 \u0648\u0639\u0644\u0649 \u0645\u062d\u0627\u062f\u062b\u0627\u062a \u0645\u0648\u0642\u0639\u0643\u060c \u064a\u0646\u0641\u0630 \u0627\u0644\u0644\u064a \u064a\u0628\u063a\u0648\u0646\u0647\u060c \u0648\u064a\u0633\u0644\u0651\u0645 \u0627\u0644\u0645\u062d\u0627\u062f\u062b\u0629 \u0644\u0645\u0648\u0638\u0641 \u0628\u0634\u0631\u064a \u2014 \u0648\u0645\u0639\u0647\u0627 \u0627\u0644\u0646\u0635 \u0627\u0644\u0643\u0627\u0645\u0644 \u0648\u0645\u0644\u062e\u0635 \u0639\u0631\u0628\u064a \u0648\u062a\u0627\u0631\u064a\u062e \u0627\u0644\u0639\u0645\u064a\u0644 \u2014 \u0623\u0648\u0644 \u0645\u0627 \u064a\u0635\u064a\u0631 \u0627\u0644\u0645\u0648\u0636\u0648\u0639 \u064a\u062d\u062a\u0627\u062c \u0625\u0646\u0633\u0627\u0646. \u064a\u0634\u062a\u063a\u0644 \u0645\u0639 \u0623\u064a \u0646\u0634\u0627\u0637\u060c \u0648\u0641\u064a\u0647 \u0642\u0648\u0627\u0644\u0628 \u062c\u0627\u0647\u0632\u0629 \u0644\u0644\u0639\u064a\u0627\u062f\u0627\u062a \u0648\u0627\u0644\u0645\u0633\u062a\u0634\u0641\u064a\u0627\u062a \u0648\u0627\u0644\u0645\u0637\u0627\u0639\u0645 \u0648\u0627\u0644\u0641\u0646\u0627\u062f\u0642 \u0648\u0627\u0644\u0639\u0642\u0627\u0631\u0627\u062a \u0648\u0627\u0644\u062a\u062c\u0632\u0626\u0629.\n\n- \u0627\u0644\u0645\u0646\u062a\u062c: \u0635\u0648\u062a \u0646\u062c\u062f\u064a / Saut Najdi\n- \u0645\u0646: \u0646\u062c\u062f\u064a AI (Najdi AI)\u060c \u0627\u0644\u0631\u064a\u0627\u0636\u060c \u0627\u0644\u0633\u0639\u0648\u062f\u064a\u0629. \u0635\u0648\u062a \u0646\u062c\u062f\u064a \u0648\u0627\u062d\u062f \u0645\u0646 \u0645\u0646\u062a\u062c\u0627\u062a\u0647\u0627\u060c \u0648najdiai.com \u0645\u0648\u0642\u0639 \u0627\u0644\u0634\u0631\u0643\u0629 \u0627\u0644\u0623\u0645 \u2014 \u0645\u0648 \u0646\u0633\u062e\u0629 \u0645\u0646 \u0647\u0630\u0627 \u0627\u0644\u0645\u0648\u0642\u0639.\n- \u0627\u0644\u0645\u0648\u0642\u0639: https://sautnajdi.ai \u2014 \u0627\u0644\u0639\u0631\u0628\u064a\u0629 \u0647\u064a \u0627\u0644\u0644\u063a\u0629 \u0627\u0644\u0623\u0633\u0627\u0633\u064a\u0629 \u0648\u062a\u0639\u064a\u0634 \u0639\u0644\u0649 \u0627\u0644\u062c\u0630\u0631\u060c \u0648\u0627\u0644\u0625\u0646\u062c\u0644\u064a\u0632\u064a\u0629 \u062a\u062d\u062a /en.\n- \u0644\u0648\u062d\u0629 \u062a\u062d\u0643\u0645 \u0627\u0644\u0639\u0645\u0644\u0627\u0621 \u0627\u0644\u062d\u0627\u0644\u064a\u064a\u0646: https://app.najdiai.com\n- \u0627\u0644\u062a\u0648\u0627\u0635\u0644: ai@sautnajdi.ai\n- \u0627\u0644\u0646\u0633\u062e\u0629 \u0627\u0644\u0625\u0646\u062c\u0644\u064a\u0632\u064a\u0629 \u0645\u0646 \u0647\u0630\u0627 \u0627\u0644\u0645\u0644\u0641: https://sautnajdi.ai/llms.txt\n- \u0622\u062e\u0631 \u0645\u0631\u0627\u062c\u0639\u0629: 2026-08-06\n\n## \u0648\u0634 \u064a\u0633\u0648\u064a \u0635\u0648\u062a \u0646\u062c\u062f\u064a\n\n- **\u064a\u0631\u062f \u0639\u0644\u0649 \u0627\u0644\u0645\u0643\u0627\u0644\u0645\u0627\u062a \u0627\u0644\u0648\u0627\u0631\u062f\u0629 \u0628\u0644\u0647\u062c\u0629 \u0633\u0639\u0648\u062f\u064a\u0629.** \u0645\u0633\u0627\u0631 \u0644\u062d\u0638\u064a: \u0635\u0648\u062a \u2190 \u0630\u0643\u0627\u0621 \u0627\u0635\u0637\u0646\u0627\u0639\u064a \u2190 \u0635\u0648\u062a\u060c \u0645\u0628\u0646\u064a \u0639\u0644\u0649 \u0627\u0644\u0639\u0631\u0628\u064a\u0629 \u0627\u0644\u0633\u0639\u0648\u062f\u064a\u0629 \u0645\u0646 \u0623\u0633\u0627\u0633\u0647 \u2014 \u0645\u0648 \u0645\u0646\u062a\u062c \u0623\u062c\u0646\u0628\u064a \u0645\u0639\u0631\u0651\u0628 \u0628\u0639\u062f\u064a\u0646.\n- **\u064a\u0642\u0628\u0644 \u0627\u0644\u0645\u0642\u0627\u0637\u0639\u0629.** \u0625\u0630\u0627 \u0642\u0627\u0637\u0639 \u0627\u0644\u0639\u0645\u064a\u0644 \u0627\u0644\u0648\u0643\u064a\u0644 \u0628\u0646\u0635 \u0627\u0644\u062c\u0645\u0644\u0629\u060c \u064a\u0633\u0643\u062a \u0639\u0644\u0649 \u0637\u0648\u0644 \u0648\u064a\u0633\u0645\u0639 \u2014 \u0645\u062b\u0644 \u0623\u064a \u0645\u0648\u0638\u0641. \u0648\u0644\u0645\u0627 \u064a\u0639\u0637\u064a \u0631\u0642\u0645 \u062d\u062c\u0632 \u0623\u0648 \u0643\u0648\u062f\u060c \u064a\u0642\u0631\u0623\u0647 \u0631\u0642\u0645 \u0631\u0642\u0645 \u0628\u0627\u0644\u0639\u0631\u0628\u064a \u0639\u0634\u0627\u0646 \u0627\u0644\u0639\u0645\u064a\u0644 \u064a\u0642\u062f\u0631 \u064a\u0643\u062a\u0628\u0647.\n- **\u064a\u0646\u0641\u0630\u060c \u0645\u0648 \u0628\u0633 \u064a\u062a\u0643\u0644\u0645.** \u064a\u062a\u062d\u0642\u0642 \u0645\u0646 \u0627\u0644\u0645\u0648\u0627\u0639\u064a\u062f \u0627\u0644\u0641\u0627\u0636\u064a\u0629 \u0648\u064a\u062d\u062c\u0632\u060c \u064a\u0633\u062c\u0644 \u062a\u0641\u0627\u0635\u064a\u0644 \u0627\u0644\u0637\u0644\u0628\u0627\u062a \u0648\u0627\u0644\u0627\u0633\u062a\u0641\u0633\u0627\u0631\u0627\u062a\u060c \u064a\u062d\u0641\u0638 \u062a\u0641\u0636\u064a\u0644\u0627\u062a \u0627\u0644\u0639\u0645\u064a\u0644\u060c \u0648\u064a\u0633\u062c\u0644 \u0637\u0644\u0628\u0627\u062a \u0627\u0644\u0627\u062a\u0635\u0627\u0644 \u0628\u0631\u0627 \u0627\u0644\u062f\u0648\u0627\u0645 \u0645\u0639 \u0627\u0644\u0648\u0642\u062a \u0627\u0644\u0644\u064a \u064a\u0646\u0627\u0633\u0628 \u0627\u0644\u0639\u0645\u064a\u0644.\n- **\u064a\u062a\u0630\u0643\u0631 \u0627\u0644\u0639\u0645\u064a\u0644 \u0627\u0644\u0631\u0627\u062c\u0639.** \u0630\u0627\u0643\u0631\u0629 \u0639\u0628\u0631 \u0627\u0644\u0645\u0643\u0627\u0644\u0645\u0627\u062a \u0644\u0643\u0644 \u0645\u0646\u0634\u0623\u0629: \u0627\u0644\u0639\u0645\u064a\u0644 \u0627\u0644\u0645\u0639\u0631\u0648\u0641 \u064a\u064f\u062d\u064a\u0651\u0649 \u0628\u0627\u0633\u0645\u0647\u060c \u0648\u062d\u062c\u0648\u0632\u0627\u062a\u0647 \u0648\u062a\u0641\u0636\u064a\u0644\u0627\u062a\u0647 \u0627\u0644\u0633\u0627\u0628\u0642\u0629 \u0642\u062f\u0627\u0645 \u0627\u0644\u0648\u0643\u064a\u0644 \u2014 \u0648\u0642\u062f\u0627\u0645 \u0627\u0644\u0645\u0648\u0638\u0641 \u0644\u0648 \u0627\u0633\u062a\u0644\u0645 \u0627\u0644\u0645\u0643\u0627\u0644\u0645\u0629.\n- **\u064a\u0633\u0644\u0651\u0645 \u0644\u0644\u0625\u0646\u0633\u0627\u0646 \u0648\u0627\u0644\u0645\u062d\u0627\u062f\u062b\u0629 \u0643\u0627\u0645\u0644\u0629 \u0645\u0639\u0647.** \u0627\u0644\u062a\u0635\u0639\u064a\u062f \u0628\u0642\u0648\u0627\u0639\u062f \u0635\u0631\u064a\u062d\u0629 \u0645\u0648 \u0628\u0627\u062c\u062a\u0647\u0627\u062f: \u0637\u0644\u0628 \u0627\u0644\u0639\u0645\u064a\u0644 \u0644\u0625\u0646\u0633\u0627\u0646 \u062a\u062d\u0648\u064a\u0644 \u0641\u0648\u0631\u064a\u060c \u0648\u0627\u0644\u0627\u0646\u0632\u0639\u0627\u062c \u0623\u0648 \u0633\u0624\u0627\u0644 \u064a\u062a\u0643\u0631\u0631 \u0628\u062f\u0648\u0646 \u062d\u0644 \u064a\u0635\u0639\u0651\u062f \u0628\u0639\u062f. \u0648\u0627\u0644\u0645\u0648\u0638\u0641 \u064a\u0633\u062a\u0644\u0645 \u0648\u0645\u0639\u0647 \u0633\u0628\u0628 \u0627\u0644\u062a\u062d\u0648\u064a\u0644\u060c \u0648\u0627\u0644\u0646\u0635 \u0627\u0644\u0643\u0627\u0645\u0644\u060c \u0648\u0645\u0644\u062e\u0635 \u0639\u0631\u0628\u064a \u0648\u0627\u0636\u062d\u060c \u0648\u062a\u0627\u0631\u064a\u062e \u0627\u0644\u0639\u0645\u064a\u0644.\n- **\u0625\u0634\u0631\u0627\u0641 \u0645\u0628\u0627\u0634\u0631.** \u0627\u0644\u0641\u0631\u064a\u0642 \u064a\u062a\u0627\u0628\u0639 \u0627\u0644\u0645\u0643\u0627\u0644\u0645\u0627\u062a \u0648\u0647\u064a \u0634\u063a\u0627\u0644\u0629 \u0645\u0646 \u0644\u0648\u062d\u0629 \u0627\u0644\u062a\u062d\u0643\u0645: \u064a\u0633\u0645\u0639\u060c \u064a\u0648\u062c\u0651\u0647 \u0627\u0644\u0648\u0643\u064a\u0644 \u0628\u0647\u0645\u0633\u0629 \u0645\u0627 \u064a\u0633\u0645\u0639\u0647\u0627 \u0627\u0644\u0639\u0645\u064a\u0644\u060c \u0623\u0648 \u064a\u0633\u062a\u0644\u0645 \u0627\u0644\u0645\u0643\u0627\u0644\u0645\u0629 \u0628\u0646\u0641\u0633\u0647.\n- **\u0642\u0646\u0648\u0627\u062a \u0646\u0635\u064a\u0629 \u0641\u064a \u0635\u0646\u062f\u0648\u0642 \u0648\u0627\u0631\u062f \u0648\u0627\u062d\u062f.** \u0648\u0627\u062a\u0633\u0627\u0628 \u0644\u0644\u0623\u0639\u0645\u0627\u0644 \u0648\u062a\u064a\u0644\u064a\u062c\u0631\u0627\u0645 \u0648\u062f\u0631\u062f\u0634\u0629 \u0627\u0644\u0645\u0648\u0642\u0639 \u062a\u0646\u0632\u0644 \u0641\u064a \u0646\u0641\u0633 \u0627\u0644\u0635\u0646\u062f\u0648\u0642 \u0627\u0644\u0644\u064a \u0641\u064a\u0647 \u0627\u0644\u0645\u0643\u0627\u0644\u0645\u0627\u062a\u060c \u0641\u0627\u0644\u0645\u0648\u0638\u0641 \u064a\u0634\u0648\u0641 \u0643\u0644 \u062a\u0627\u0631\u064a\u062e \u0627\u0644\u0639\u0645\u064a\u0644 \u0641\u064a \u0645\u0643\u0627\u0646 \u0648\u0627\u062d\u062f.\n- **\u0642\u0627\u0639\u062f\u0629 \u0645\u0639\u0631\u0641\u0629 \u0639\u0631\u0628\u064a\u0629 \u0645\u0646 \u0645\u0644\u0641\u0627\u062a\u0643 \u0623\u0646\u062a.** \u0645\u0644\u0641\u0627\u062a PDF \u0648Word \u2014 \u062d\u062a\u0649 \u0627\u0644\u0645\u0645\u0633\u0648\u062d\u0629 \u0636\u0648\u0626\u064a\u0627\u064b \u2014 \u0639\u0628\u0631 \u062a\u0639\u0631\u0651\u0641 \u0636\u0648\u0626\u064a \u0639\u0631\u0628\u064a \u062d\u0642\u064a\u0642\u064a \u064a\u062a\u0639\u0627\u0645\u0644 \u0645\u0639 \u0627\u062a\u0635\u0627\u0644 \u0627\u0644\u062d\u0631\u0648\u0641 \u0648\u0631\u0633\u0645\u0647\u0627 \u0628\u0634\u0643\u0644 \u0635\u062d\u064a\u062d\u060c \u0628\u0627\u0644\u0625\u0636\u0627\u0641\u0629 \u0644\u0623\u0633\u0626\u0644\u0629 \u0648\u0623\u062c\u0648\u0628\u0629 \u0648\u0631\u0648\u0627\u0628\u0637 \u0648\u0645\u0642\u062a\u0637\u0641\u0627\u062a \u0648\u0623\u0648\u0642\u0627\u062a \u0627\u0644\u062f\u0648\u0627\u0645\u060c \u0645\u0641\u0647\u0631\u0633\u0629 \u0628\u0627\u0644\u0645\u0639\u0646\u0649 \u0645\u0648 \u0628\u0627\u0644\u0643\u0644\u0645\u0629.\n- **\u0628\u0646\u0627\u0621 \u0627\u0644\u0648\u0643\u064a\u0644 \u0628\u062f\u0648\u0646 \u0643\u0648\u062f.** \u0642\u0648\u0627\u0644\u0628 \u0644\u0643\u0644 \u0642\u0637\u0627\u0639\u060c \u0648\u062a\u062d\u0643\u0651\u0645 \u0628\u0634\u062e\u0635\u064a\u0629 \u0627\u0644\u0648\u0643\u064a\u0644\u060c \u0648\u062a\u0648\u0644\u064a\u062f \u0646\u0635 \u0627\u0644\u0634\u062e\u0635\u064a\u0629 \u0628\u0627\u0644\u0644\u0647\u062c\u0629 \u0627\u0644\u0646\u062c\u062f\u064a\u0629 \u0628\u0627\u0644\u0630\u0643\u0627\u0621 \u0627\u0644\u0627\u0635\u0637\u0646\u0627\u0639\u064a\u060c \u0648\u062f\u0631\u062f\u0634\u0629 \u062a\u062c\u0631\u064a\u0628\u064a\u0629\u060c \u0648\u0627\u062e\u062a\u0628\u0627\u0631\u0627\u062a \u0633\u064a\u0646\u0627\u0631\u064a\u0648 \u0645\u062d\u0641\u0648\u0638\u0629\u060c \u0648\u0646\u0634\u0631 \u0645\u062a\u0639\u0645\u0651\u062f: \u0645\u0633\u0648\u062f\u0629 \u2190 \u0646\u0634\u0631 \u0645\u0639 \u062a\u0627\u0631\u064a\u062e \u0646\u0633\u062e \u0648\u0645\u0642\u0627\u0631\u0646\u0629 \u062a\u0628\u064a\u0651\u0646 \u0648\u0634 \u062a\u063a\u064a\u0651\u0631.\n- **\u0623\u062a\u0645\u062a\u0629 \u0645\u0633\u0627\u0631\u0627\u062a \u0639\u0645\u0644 \u0628\u0635\u0631\u064a\u0629**\u060c \u0648**\u0644\u0648\u062d\u0629 \u062a\u062d\u0643\u0645** \u0641\u064a\u0647\u0627 \u0633\u062c\u0644 \u0627\u0644\u0645\u0643\u0627\u0644\u0645\u0627\u062a \u0648\u0627\u0644\u0646\u0635\u0648\u0635 \u0648\u0627\u0644\u062a\u0633\u062c\u064a\u0644\u0627\u062a \u0648\u0627\u0644\u0645\u0644\u062e\u0635\u0627\u062a \u0648\u0627\u0644\u0645\u0634\u0627\u0639\u0631 \u0648\u0627\u0644\u062a\u0642\u064a\u064a\u0645\u0627\u062a \u0648\u0627\u0644\u0648\u0633\u0648\u0645\u060c \u0648\u0645\u0644\u0641 \u0644\u0643\u0644 \u0639\u0645\u064a\u0644 \u0628\u062a\u0627\u0631\u064a\u062e\u0647 \u0627\u0644\u0643\u0627\u0645\u0644\u060c \u0648\u062a\u0642\u0648\u064a\u0645 \u062d\u062c\u0648\u0632\u0627\u062a \u064a\u062f\u064a\u0631\u0647 \u0627\u0644\u0641\u0631\u064a\u0642.\n- **\u0648\u0627\u062c\u0647\u0629 \u0628\u0631\u0645\u062c\u064a\u0629 \u0639\u0627\u0645\u0629 \u0644\u0644\u0642\u0631\u0627\u0621\u0629** \u0628\u0645\u0641\u0627\u062a\u064a\u062d \u0645\u062d\u062f\u0648\u062f\u0629 \u0627\u0644\u0635\u0644\u0627\u062d\u064a\u0627\u062a.\n\n## \u0627\u0644\u0644\u0647\u062c\u0627\u062a \u0648\u0627\u0644\u0644\u063a\u0627\u062a\n\n\u0627\u0644\u0623\u0635\u0648\u0627\u062a \u0627\u0644\u0645\u062a\u0648\u0641\u0631\u0629 \u0627\u0644\u064a\u0648\u0645: \u0631\u062c\u0627\u0644\u064a\u0629 \u0648\u0646\u0633\u0627\u0626\u064a\u0629 \u2014 **\u0646\u062c\u062f\u064a** \u0648**\u062d\u062c\u0627\u0632\u064a** \u0645\u0646 \u0627\u0644\u0644\u0647\u062c\u0627\u062a \u0627\u0644\u0633\u0639\u0648\u062f\u064a\u0629\u060c \u0628\u0627\u0644\u0625\u0636\u0627\u0641\u0629 \u0625\u0644\u0649 **\u0634\u0627\u0645\u064a** \u0648**\u0627\u0644\u0625\u0646\u062c\u0644\u064a\u0632\u064a\u0629**. \u0648\u0645\u0627 \u0646\u0639\u0644\u0646 \u0644\u0647\u062c\u0627\u062a \u0645\u0627 \u0647\u064a \u062c\u0627\u0647\u0632\u0629 \u0639\u0646\u062f\u0646\u0627 \u0641\u0639\u0644\u0627\u064b. \u0648\u062a\u0642\u062f\u0631 \u062a\u0636\u064a\u0641 \u0635\u0648\u062a \u0639\u0644\u0627\u0645\u062a\u0643 \u0628\u0627\u0633\u062a\u0646\u0633\u0627\u062e \u0635\u0648\u062a \u0634\u062e\u0635 \u0628\u0639\u064a\u0646\u0647: \u0639\u064a\u0651\u0646\u0629 60 \u062b\u0627\u0646\u064a\u0629 \u0639\u0644\u0649 \u0627\u0644\u0623\u0642\u0644\u060c \u0648\u0625\u0642\u0631\u0627\u0631 \u0645\u0648\u0627\u0641\u0642\u0629 \u0645\u0633\u062c\u0651\u0644 \u0628\u0627\u0633\u0645 \u0635\u0627\u062d\u0628 \u0627\u0644\u0635\u0648\u062a\u060c \u0648\u062a\u062e\u062a\u0627\u0631\u0647 \u0644\u0648\u0643\u064a\u0644\u0643 \u0645\u062b\u0644 \u0623\u064a \u0635\u0648\u062a \u062b\u0627\u0646\u064a. \u0648\u0627\u0644\u0645\u0648\u0627\u0641\u0642\u0629 \u062a\u0646\u0633\u062d\u0628 \u0628\u0623\u064a \u0644\u062d\u0638\u0629: \u0627\u0644\u0635\u0648\u062a \u064a\u0648\u0642\u0641 \u0639\u0644\u0649 \u0637\u0648\u0644 \u0648\u064a\u064f\u062d\u0630\u0641 \u0646\u0647\u0627\u0626\u064a\u0627\u064b \u062e\u0644\u0627\u0644 30 \u064a\u0648\u0645\u0627\u064b. \u0648\u0627\u0644\u0625\u062a\u0627\u062d\u0629 \u062d\u0633\u0628 \u0628\u0627\u0642\u062a\u0643. \u0627\u0644\u0627\u0633\u062a\u0646\u0633\u0627\u062e \u064a\u0646\u0633\u062e \u0635\u0648\u062a \u0627\u0644\u0634\u062e\u0635 \u0646\u0641\u0633\u0647\u060c \u0645\u0648 \u0644\u0647\u062c\u0629 \u0645\u062d\u0627\u062f\u062b\u0629 \u062c\u062f\u064a\u062f\u0629.\n\n## \u0627\u0644\u0628\u064a\u0627\u0646\u0627\u062a \u0648\u0627\u0644\u062a\u062e\u0632\u064a\u0646 \u0648\u0627\u0644\u062a\u0648\u0627\u0641\u0642 \u0645\u0639 PDPL\n\n\u0645\u0635\u0645\u0651\u0645 \u0628\u0645\u0627 \u064a\u062a\u0648\u0627\u0641\u0642 \u0645\u0639 \u0646\u0638\u0627\u0645 \u062d\u0645\u0627\u064a\u0629 \u0627\u0644\u0628\u064a\u0627\u0646\u0627\u062a \u0627\u0644\u0634\u062e\u0635\u064a\u0629 \u0627\u0644\u0633\u0639\u0648\u062f\u064a (PDPL) \u2014 \u0628\u064a\u0627\u0646\u0627\u062a\u0643 \u0645\u062e\u0632\u0651\u0646\u0629 \u0641\u064a \u0645\u0646\u0637\u0642\u0629 \u0627\u0644\u062e\u0644\u064a\u062c\u060c \u0645\u0639 \u0625\u0641\u0635\u0627\u062d \u0643\u0627\u0645\u0644 \u0639\u0646 \u0623\u0645\u0627\u0643\u0646 \u0627\u0644\u0645\u0639\u0627\u0644\u062c\u0629.\n\n\u0648\u0628\u0627\u0644\u062a\u0641\u0635\u064a\u0644 \u0627\u0644\u062f\u0642\u064a\u0642\u060c \u0644\u0623\u0646 \u0627\u0644\u062f\u0642\u0629 \u0647\u064a \u062c\u0648\u0647\u0631 \u0627\u0644\u0627\u0645\u062a\u062b\u0627\u0644:\n\n- \u0627\u0644\u062a\u062e\u0632\u064a\u0646 \u0627\u0644\u062f\u0627\u0626\u0645: \u0642\u0648\u0627\u0639\u062f \u0628\u064a\u0627\u0646\u0627\u062a Cloud SQL PostgreSQL \u0641\u064a **\u0645\u0646\u0637\u0642\u0629 \u0627\u0644\u062e\u0644\u064a\u062c (\u0627\u0644\u062f\u0648\u062d\u0629 \u2014 me-central1)** \u0639\u0644\u0649 Google Cloud\u060c \u0639\u0628\u0631 \u0634\u0628\u0643\u0629 \u062e\u0627\u0635\u0629 \u0641\u0642\u0637\u060c \u0645\u0639 \u0646\u0633\u062e \u0627\u062d\u062a\u064a\u0627\u0637\u064a\u0629 \u0648\u0627\u0633\u062a\u0639\u0627\u062f\u0629 \u0644\u0646\u0642\u0637\u0629 \u0632\u0645\u0646\u064a\u0629 \u0645\u062d\u062f\u062f\u0629.\n- \u062a\u0633\u062c\u064a\u0644\u0627\u062a \u0627\u0644\u0645\u0643\u0627\u0644\u0645\u0627\u062a: \u0641\u064a \u0646\u0641\u0633 \u0627\u0644\u0645\u0646\u0637\u0642\u0629\u060c \u0648**\u062a\u064f\u062d\u0630\u0641 \u062a\u0644\u0642\u0627\u0626\u064a\u0627\u064b \u0628\u0639\u062f 90 \u064a\u0648\u0645\u0627\u064b**\u060c \u0648\u0644\u0627 \u062a\u064f\u0641\u062a\u062d \u0625\u0644\u0627 \u0639\u0628\u0631 \u0631\u0648\u0627\u0628\u0637 \u0645\u0648\u0642\u0651\u0639\u0629 \u0642\u0635\u064a\u0631\u0629 \u0627\u0644\u0635\u0644\u0627\u062d\u064a\u0629.\n- \u0627\u0644\u0625\u0641\u0635\u0627\u062d \u0639\u0646 \u0627\u0644\u0645\u0639\u0627\u0644\u062c\u0629: \u0627\u0644\u0645\u0639\u0627\u0644\u062c\u0629 \u0627\u0644\u0644\u062d\u0638\u064a\u0629 \u0644\u0644\u0635\u0648\u062a \u0648\u0627\u0644\u0630\u0643\u0627\u0621 \u0627\u0644\u0627\u0635\u0637\u0646\u0627\u0639\u064a \u2014 \u062a\u062d\u0648\u064a\u0644 \u0627\u0644\u0643\u0644\u0627\u0645 \u0625\u0644\u0649 \u0646\u0635\u060c \u0648\u0641\u0647\u0645 \u0627\u0644\u0644\u063a\u0629\u060c \u0648\u062a\u0648\u0644\u064a\u062f \u0627\u0644\u0635\u0648\u062a \u2014 **\u062a\u0645\u0631 \u0639\u0628\u0631 \u0645\u0632\u0648\u0651\u062f\u064a\u0646 \u0639\u0627\u0644\u0645\u064a\u064a\u0646**\u060c \u0648\u0645\u0639\u0627\u0644\u062c\u0629 \u0645\u0633\u062a\u0646\u062f\u0627\u062a \u0642\u0627\u0639\u062f\u0629 \u0627\u0644\u0645\u0639\u0631\u0641\u0629 (\u0627\u0644\u062a\u0639\u0631\u0651\u0641 \u0627\u0644\u0636\u0648\u0626\u064a) \u062a\u0645\u0631 \u0639\u0628\u0631 **\u0646\u0642\u0637\u0629 \u0645\u0639\u0627\u0644\u062c\u0629 \u0623\u0648\u0631\u0648\u0628\u064a\u0629**. \u0635\u0648\u062a \u0646\u062c\u062f\u064a **\u0644\u0627** \u064a\u062f\u0651\u0639\u064a \u0623\u0646 \u0643\u0644 \u0627\u0644\u0628\u064a\u0627\u0646\u0627\u062a \u0648\u0643\u0644 \u0627\u0644\u0645\u0639\u0627\u0644\u062c\u0629 \u062f\u0627\u062e\u0644 \u0627\u0644\u0633\u0639\u0648\u062f\u064a\u0629\u061b \u0648\u0627\u0644\u0625\u0641\u0635\u0627\u062d \u0639\u0646 \u0627\u0644\u0646\u0642\u0644 \u0639\u0628\u0631 \u0627\u0644\u062d\u062f\u0648\u062f \u0647\u0648 \u0645\u0627 \u064a\u062a\u0637\u0644\u0628\u0647 \u0627\u0644\u0646\u0638\u0627\u0645.\n- **\u0633\u062c\u0644 \u062a\u062f\u0642\u064a\u0642 \u063a\u064a\u0631 \u0642\u0627\u0628\u0644 \u0644\u0644\u062a\u0639\u062f\u064a\u0644** \u062a\u0641\u0631\u0636\u0647 \u0642\u0627\u0639\u062f\u0629 \u0627\u0644\u0628\u064a\u0627\u0646\u0627\u062a \u0646\u0641\u0633\u0647\u0627: \u0645\u0627 \u064a\u0646\u0639\u062f\u0644 \u0648\u0644\u0627 \u064a\u0646\u062d\u0630\u0641 \u0623\u064a \u0633\u0637\u0631 \u2014 \u0648\u0644\u0627 \u062d\u062a\u0649 \u0645\u0646 \u0645\u0633\u0624\u0648\u0644 \u0627\u0644\u0646\u0638\u0627\u0645.\n- \u0623\u062f\u0648\u0627\u0631 \u0648\u0635\u0644\u0627\u062d\u064a\u0627\u062a \u0644\u0643\u0644 \u0645\u0648\u0638\u0641\u060c \u0648\u0639\u0632\u0644 \u062a\u0627\u0645 \u0644\u0628\u064a\u0627\u0646\u0627\u062a \u0643\u0644 \u0639\u0645\u064a\u0644 \u0639\u0644\u0649 \u0645\u0633\u062a\u0648\u0649 \u0642\u0627\u0639\u062f\u0629 \u0627\u0644\u0628\u064a\u0627\u0646\u0627\u062a\u060c \u0648\u0648\u0635\u0648\u0644 \u0645\u064f\u062f\u0642\u064e\u0651\u0642 \u0644\u0641\u0631\u064a\u0642 \u0627\u0644\u062f\u0639\u0645.\n- \u0627\u0644\u062a\u0641\u0627\u0635\u064a\u0644 \u0627\u0644\u0643\u0627\u0645\u0644\u0629: https://sautnajdi.ai/security \u2014 \u0648\u0623\u0645\u0627\u0643\u0646 \u0627\u0644\u0645\u0639\u0627\u0644\u062c\u0629 \u0648\u0641\u0626\u0627\u062a \u0627\u0644\u0645\u0639\u0627\u0644\u062c\u064a\u0646 \u0645\u0641\u0635\u062d \u0639\u0646\u0647\u0627 \u0641\u064a https://sautnajdi.ai/privacy\n\n## \u0648\u0634 \u0645\u0627 \u064a\u0633\u0648\u064a\u0647 \u0635\u0648\u062a \u0646\u062c\u062f\u064a\n\n\u0646\u0642\u0648\u0644\u0647\u0627 \u0628\u0635\u0631\u0627\u062d\u0629 \u0639\u0634\u0627\u0646 \u0645\u0627 \u064a\u0633\u062a\u0646\u062a\u062c\u0647\u0627 \u0623\u062d\u062f \u0645\u0646 \u0627\u0644\u0633\u0643\u0648\u062a:\n\n- \u0645\u0627 \u0641\u064a\u0647 \u0627\u062a\u0635\u0627\u0644 \u0622\u0644\u064a \u0639\u0644\u0649 \u0642\u0648\u0627\u0626\u0645 \u0623\u0631\u0642\u0627\u0645. \u0627\u0644\u0645\u0643\u0627\u0644\u0645\u0627\u062a \u0627\u0644\u0635\u0627\u062f\u0631\u0629 \u0645\u0648\u062c\u0648\u062f\u0629 \u2014 \u0641\u0631\u064a\u0642\u0643 \u064a\u0637\u0644\u0639\u0647\u0627 \u0645\u0646 \u0627\u0644\u0644\u0648\u062d\u0629 \u0648\u0627\u0644\u0648\u0643\u064a\u0644 \u064a\u0645\u0633\u0643 \u0627\u0644\u062d\u0648\u0627\u0631 \u2014 \u0644\u0643\u0646 \u0645\u0627 \u0641\u064a\u0647 \u0634\u064a \u064a\u062a\u0635\u0644 \u0645\u0646 \u0646\u0641\u0633\u0647\u060c \u0648\u0644\u0627 \u062d\u0645\u0644\u0627\u062a \u0627\u062a\u0635\u0627\u0644 \u0622\u0644\u064a\u0629.\n- \u0645\u0627 \u0641\u064a\u0647 \u0631\u0642\u0645 \u0633\u0639\u0648\u062f\u064a \u062a\u062a\u0635\u0644 \u0639\u0644\u064a\u0647 \u0648\u062a\u062c\u0631\u0628. \u062a\u0641\u0639\u064a\u0644 \u0627\u0644\u0623\u0631\u0642\u0627\u0645 \u064a\u0645\u0631 \u0628\u0625\u062c\u0631\u0627\u0621\u0627\u062a \u0627\u0644\u062c\u0647\u0627\u062a \u0627\u0644\u062a\u0646\u0638\u064a\u0645\u064a\u0629 \u0644\u0644\u0627\u062a\u0635\u0627\u0644\u0627\u062a\u060c \u0639\u0634\u0627\u0646 \u0643\u0630\u0627 \u0627\u0644\u062a\u062c\u0631\u0628\u0629 \u062a\u0635\u064a\u0631 \u0641\u064a \u0627\u0644\u0639\u0631\u0636 \u0627\u0644\u062a\u0639\u0631\u064a\u0641\u064a.\n- \u0645\u0627 \u0641\u064a\u0647 \u0642\u0646\u0627\u0629 \u0631\u0633\u0627\u0626\u0644 SMS \u0648\u0644\u0627 \u0628\u0631\u064a\u062f \u0625\u0644\u0643\u062a\u0631\u0648\u0646\u064a \u0643\u0642\u0646\u0627\u0629 \u0631\u062f.\n- \u0645\u0627 \u0641\u064a\u0647 \u0623\u0633\u0639\u0627\u0631 \u0645\u0639\u0644\u0646\u0629 \u0648\u0644\u0627 \u062a\u0633\u062c\u064a\u0644 \u0630\u0627\u062a\u064a. \u0627\u0644\u0641\u0631\u064a\u0642 \u064a\u062c\u0647\u0632 \u0643\u0644 \u0639\u0645\u064a\u0644\u060c \u0648\u0627\u0644\u0633\u0639\u0631 \u064a\u062c\u064a \u0628\u0639\u062f \u0627\u0644\u0639\u0631\u0636 \u0627\u0644\u062a\u0639\u0631\u064a\u0641\u064a.\n- \u0645\u0627 \u0641\u064a\u0647 \u0623\u0631\u0642\u0627\u0645 \u0623\u062f\u0627\u0621 \u0645\u0646\u0634\u0648\u0631\u0629 \u2014 \u0644\u0627 \u0646\u0633\u0628\u0629 \u062f\u0642\u0629\u060c \u0648\u0644\u0627 \u0631\u0636\u0627\u060c \u0648\u0644\u0627 \u0632\u0645\u0646 \u0627\u0633\u062a\u062c\u0627\u0628\u0629\u060c \u0648\u0644\u0627 \u0646\u0633\u0628\u0629 \u062a\u0648\u0641\u064a\u0631 \u2014 \u0648\u0645\u0627 \u0641\u064a\u0647 \u0623\u0633\u0645\u0627\u0621 \u0639\u0645\u0644\u0627\u0621 \u0648\u0644\u0627 \u0634\u0639\u0627\u0631\u0627\u062a \u0648\u0644\u0627 \u0642\u0635\u0635 \u0646\u062c\u0627\u062d. \u0644\u0623\u0646\u0647\u0627 \u0645\u0627 \u0642\u064a\u0633\u062a \u0628\u0634\u0643\u0644 \u0646\u062f\u0627\u0641\u0639 \u0639\u0646\u0647\u060c \u0648\u0645\u0627 \u0623\u062e\u0630\u0646\u0627 \u0645\u0648\u0627\u0641\u0642\u0629 \u0623\u062d\u062f.\n- \u0635\u0648\u062a \u0646\u062c\u062f\u064a \u0645\u0627 \u064a\u0639\u0648\u0651\u0636 \u0639\u0646 \u0623\u064a \u0627\u0644\u062a\u0632\u0627\u0645 \u0646\u0638\u0627\u0645\u064a \u0628\u062a\u0648\u0637\u064a\u0646 \u0645\u0647\u0646 \u062e\u062f\u0645\u0629 \u0627\u0644\u0639\u0645\u0644\u0627\u0621. \u0627\u0644\u0645\u0631\u062c\u0639 \u0641\u064a \u0645\u062a\u0637\u0644\u0628\u0627\u062a \u0627\u0644\u062a\u0648\u0637\u064a\u0646 \u0647\u0648 \u0648\u0632\u0627\u0631\u0629 \u0627\u0644\u0645\u0648\u0627\u0631\u062f \u0627\u0644\u0628\u0634\u0631\u064a\u0629 \u0648\u0627\u0644\u062a\u0646\u0645\u064a\u0629 \u0627\u0644\u0627\u062c\u062a\u0645\u0627\u0639\u064a\u0629. \u0627\u0644\u0644\u064a \u064a\u0633\u0648\u064a\u0647 \u0627\u0644\u0645\u0646\u062a\u062c \u0625\u0646\u0647 \u064a\u0631\u062f \u0639\u0644\u0649 \u0627\u0644\u0645\u0643\u0627\u0644\u0645\u0627\u062a \u0627\u0644\u0631\u0648\u062a\u064a\u0646\u064a\u0629 \u0627\u0644\u0645\u062a\u0643\u0631\u0631\u0629 \u0648\u064a\u062e\u0644\u064a \u0641\u0631\u064a\u0642 \u0627\u0644\u0645\u0646\u0634\u0623\u0629 \u0645\u062a\u0641\u0631\u063a \u0644\u0644\u0645\u0643\u0627\u0644\u0645\u0627\u062a \u0627\u0644\u0644\u064a \u062a\u062d\u062a\u0627\u062c \u0625\u0646\u0633\u0627\u0646.\n\n## \u0643\u064a\u0641 \u062a\u0628\u062f\u0623\n\n\u0627\u062d\u062c\u0632 \u0639\u0631\u0636\u0627\u064b \u062a\u0639\u0631\u064a\u0641\u064a\u0627\u064b \u0645\u062f\u062a\u0647 30 \u062f\u0642\u064a\u0642\u0629 \u0645\u0646 https://sautnajdi.ai/demo \u2014 \u0646\u0648\u0631\u064a\u0643 \u0627\u0644\u0645\u0646\u0635\u0629 \u062d\u064a\u0629\u060c \u0648\u062a\u0633\u0645\u0639 \u0627\u0644\u0648\u0643\u064a\u0644 \u0628\u0644\u0647\u062c\u062a\u0643\u060c \u0648\u0646\u062c\u0627\u0648\u0628 \u0623\u0633\u0626\u0644\u0629 \u0627\u0644\u0623\u0645\u0627\u0646 \u0648\u0627\u0644\u0628\u064a\u0627\u0646\u0627\u062a \u0648PDPL \u0641\u064a \u0646\u0641\u0633 \u0627\u0644\u062c\u0644\u0633\u0629\u060c \u0648\u0628\u0639\u062f\u0647\u0627 \u0646\u0631\u0633\u0644 \u0644\u0643 \u0639\u0631\u0636 \u0633\u0639\u0631 \u0645\u0643\u062a\u0648\u0628 \u0639\u0644\u0649 \u0642\u062f \u062d\u062c\u0645 \u0645\u0643\u0627\u0644\u0645\u0627\u062a\u0643 \u0648\u0642\u0646\u0648\u0627\u062a\u0643. \u0648\u0625\u0630\u0627 \u062a\u0628\u064a \u062a\u0633\u0623\u0644 \u0642\u0628\u0644\u060c \u0641\u064a\u0647 \u0645\u0643\u0627\u0644\u0645\u0629 \u0633\u0631\u064a\u0639\u0629 15 \u062f\u0642\u064a\u0642\u0629. \u0627\u0644\u062d\u062c\u0632 \u0643\u0644\u0647 \u0639\u0628\u0631 Cal.com.\n\n## \u0623\u0633\u0626\u0644\u0629 \u0648\u0623\u062c\u0648\u0628\u0629\n\n**\u0648\u0634 \u0647\u0648 \u0635\u0648\u062a \u0646\u062c\u062f\u064a\u061f** \u0635\u0648\u062a \u0646\u062c\u062f\u064a \u0648\u0643\u064a\u0644 \u0635\u0648\u062a\u064a \u0633\u0639\u0648\u062f\u064a \u0628\u0627\u0644\u0630\u0643\u0627\u0621 \u0627\u0644\u0627\u0635\u0637\u0646\u0627\u0639\u064a \u064a\u0631\u062f \u0639\u0644\u0649 \u0645\u0643\u0627\u0644\u0645\u0627\u062a \u0639\u0645\u0644\u0627\u0626\u0643 \u0628\u0627\u0644\u0644\u0647\u062c\u0629 \u0627\u0644\u0644\u064a \u064a\u0641\u0647\u0645\u0648\u0646\u0647\u0627\u060c \u064a\u0646\u0641\u0630 \u0637\u0644\u0628\u0627\u062a\u0647\u0645 \u2014 \u064a\u062d\u062c\u0632 \u0648\u064a\u062c\u0627\u0648\u0628 \u0648\u064a\u0633\u062c\u0644 \u2014 \u0648\u064a\u062d\u0648\u0651\u0644 \u0627\u0644\u0645\u0643\u0627\u0644\u0645\u0629 \u0644\u0645\u0648\u0638\u0641\u0643 \u0627\u0644\u0628\u0634\u0631\u064a \u0628\u0643\u0627\u0645\u0644 \u0633\u064a\u0627\u0642\u0647\u0627 \u0645\u062a\u0649 \u0645\u0627 \u0627\u062d\u062a\u0627\u062c \u0627\u0644\u0645\u0648\u0636\u0648\u0639 \u0625\u0646\u0633\u0627\u0646.\n\n**\u064a\u0641\u0647\u0645 \u0627\u0644\u0644\u0647\u062c\u0629 \u0627\u0644\u0633\u0639\u0648\u062f\u064a\u0629 \u0641\u0639\u0644\u0627\u064b\u061f** \u0635\u0648\u062a \u0646\u062c\u062f\u064a \u0645\u0628\u0646\u064a \u0645\u0646 \u0623\u0633\u0627\u0633\u0647 \u0639\u0644\u0649 \u0627\u0644\u0644\u0647\u062c\u0627\u062a \u0627\u0644\u0633\u0639\u0648\u062f\u064a\u0629: \u064a\u0633\u0645\u0639 \u00ab\u0623\u0628\u063a\u0649\u00bb \u0648\u00ab\u0648\u0634\u00bb \u0648\u00ab\u0628\u0643\u0631\u0629\u00bb \u0648\u064a\u0641\u0647\u0645\u0647\u0627 \u0635\u062d\u060c \u0648\u064a\u0631\u062f \u0628\u0623\u0635\u0648\u0627\u062a \u0631\u062c\u0627\u0644\u064a\u0629 \u0648\u0646\u0633\u0627\u0626\u064a\u0629: \u0646\u062c\u062f\u064a \u0648\u062d\u062c\u0627\u0632\u064a \u0648\u0634\u0627\u0645\u064a \u0648\u0625\u0646\u062c\u0644\u064a\u0632\u064a.\n\n**\u0648\u0634 \u0627\u0644\u0641\u0631\u0642 \u0628\u064a\u0646 \u0627\u0644\u0631\u062f \u0627\u0644\u0622\u0644\u064a (IVR) \u0648\u0627\u0644\u0648\u0643\u064a\u0644 \u0627\u0644\u0635\u0648\u062a\u064a \u0627\u0644\u0630\u0643\u064a\u061f** \u0635\u0648\u062a \u0646\u062c\u062f\u064a \u0648\u0643\u064a\u0644 \u0635\u0648\u062a\u064a \u064a\u062a\u0643\u0644\u0645 \u0645\u0639 \u0639\u0645\u064a\u0644\u0643 \u0628\u0644\u063a\u062a\u0647 \u0627\u0644\u0637\u0628\u064a\u0639\u064a\u0629\u060c \u0645\u0648 \u0642\u0627\u0626\u0645\u0629 \u00ab\u0627\u0636\u063a\u0637 1\u00bb: \u0627\u0644\u0639\u0645\u064a\u0644 \u064a\u0642\u0648\u0644 \u00ab\u0623\u0628\u063a\u0649 \u0623\u062d\u062c\u0632 \u0628\u0643\u0631\u0629 \u0627\u0644\u0639\u0635\u0631\u00bb \u0628\u0644\u0647\u062c\u062a\u0647\u060c \u0648\u0627\u0644\u0648\u0643\u064a\u0644 \u064a\u0641\u0647\u0645 \u0642\u0635\u062f\u0647 \u0648\u064a\u062d\u062c\u0632 \u0644\u0647 \u0645\u0628\u0627\u0634\u0631\u0629\u060c \u0648\u064a\u0642\u062f\u0631 \u0627\u0644\u0639\u0645\u064a\u0644 \u064a\u0642\u0627\u0637\u0639\u0647 \u0628\u0646\u0635 \u0627\u0644\u062c\u0645\u0644\u0629 \u0632\u064a \u0645\u0627 \u064a\u0642\u0627\u0637\u0639 \u0623\u064a \u0645\u0648\u0638\u0641 \u2014 \u0628\u064a\u0646\u0645\u0627 \u0646\u0638\u0627\u0645 IVR \u0627\u0644\u062a\u0642\u0644\u064a\u062f\u064a \u064a\u0639\u0637\u064a\u0643 \u062e\u064a\u0627\u0631\u0627\u062a \u062b\u0627\u0628\u062a\u0629 \u0648\u0644\u0627\u0632\u0645 \u062a\u0645\u0634\u064a \u0639\u0644\u064a\u0647\u0627.\n\n**\u0645\u062a\u0649 \u062a\u0631\u0648\u062d \u0627\u0644\u0645\u0643\u0627\u0644\u0645\u0629 \u0644\u0645\u0648\u0638\u0641 \u0628\u0634\u0631\u064a\u061f** \u0627\u0644\u0645\u0643\u0627\u0644\u0645\u0629 \u0641\u064a \u0635\u0648\u062a \u0646\u062c\u062f\u064a \u062a\u0631\u0648\u062d \u0644\u0645\u0648\u0638\u0641\u0643 \u0641\u0648\u0631\u0627\u064b \u0625\u0630\u0627 \u0637\u0644\u0628 \u0627\u0644\u0639\u0645\u064a\u0644 \u0625\u0646\u0633\u0627\u0646\u060c \u0623\u0648 \u0625\u0630\u0627 \u0643\u0627\u0646 \u0645\u0646\u0632\u0639\u062c\u060c \u0623\u0648 \u0625\u0630\u0627 \u062a\u0643\u0631\u0631 \u0633\u0624\u0627\u0644 \u0645\u0627 \u0627\u0646\u062d\u0644 \u2014 \u0648\u0642\u0648\u0627\u0639\u062f \u0627\u0644\u062a\u0635\u0639\u064a\u062f \u0623\u0646\u062a \u0627\u0644\u0644\u064a \u062a\u062d\u062f\u062f\u0647\u0627. \u0648\u0645\u0648\u0638\u0641\u0643 \u064a\u0633\u062a\u0644\u0645 \u0648\u0645\u0639\u0647 \u0627\u0644\u0646\u0635 \u0627\u0644\u0643\u0627\u0645\u0644 \u0648\u0627\u0644\u0645\u0644\u062e\u0635 \u0648\u062a\u0627\u0631\u064a\u062e \u0627\u0644\u0639\u0645\u064a\u0644.\n\n**\u0623\u0642\u062f\u0631 \u0623\u0633\u0645\u0639 \u0627\u0644\u0645\u0643\u0627\u0644\u0645\u0629 \u0648\u0647\u064a \u0634\u063a\u0627\u0644\u0629 \u0648\u0623\u0633\u062a\u0644\u0645\u0647\u0627\u061f** \u0641\u064a \u0644\u0648\u062d\u0629 \u0635\u0648\u062a \u0646\u062c\u062f\u064a \u0641\u0631\u064a\u0642\u0643 \u064a\u062a\u0627\u0628\u0639 \u0627\u0644\u0645\u0643\u0627\u0644\u0645\u0627\u062a \u0627\u0644\u062d\u064a\u0629\u060c \u064a\u0633\u0645\u0639 \u0623\u064a \u0645\u0643\u0627\u0644\u0645\u0629\u060c \u064a\u0648\u062c\u0651\u0647 \u0627\u0644\u0648\u0643\u064a\u0644 \u0628\u0647\u0645\u0633\u0629 \u0645\u0627 \u064a\u0633\u0645\u0639\u0647\u0627 \u0627\u0644\u0639\u0645\u064a\u0644\u060c \u0623\u0648 \u064a\u0633\u062a\u0644\u0645 \u0627\u0644\u0645\u0643\u0627\u0644\u0645\u0629 \u0628\u0636\u063a\u0637\u0629 \u0648\u062d\u062f\u0629.\n\n**\u0627\u0644\u0648\u0643\u064a\u0644 \u064a\u0633\u0643\u062a \u0625\u0630\u0627 \u0642\u0627\u0637\u0639\u0647 \u0627\u0644\u0639\u0645\u064a\u0644\u061f** \u0648\u0643\u064a\u0644 \u0635\u0648\u062a \u0646\u062c\u062f\u064a \u064a\u0633\u0643\u062a \u0639\u0644\u0649 \u0637\u0648\u0644 \u0625\u0630\u0627 \u0642\u0627\u0637\u0639\u0647 \u0627\u0644\u0639\u0645\u064a\u0644 \u0628\u0646\u0635 \u0627\u0644\u062c\u0645\u0644\u0629 \u0648\u064a\u0633\u0645\u0639 \u0644\u0647 \u2014 \u0645\u062b\u0644 \u0623\u064a \u0645\u0648\u0638\u0641. \u0648\u0644\u0645\u0627 \u064a\u0639\u0637\u064a \u0627\u0644\u0639\u0645\u064a\u0644 \u0631\u0642\u0645 \u062d\u062c\u0632 \u0623\u0648 \u0643\u0648\u062f\u060c \u064a\u0642\u0631\u0623\u0647 \u0631\u0642\u0645 \u0631\u0642\u0645 \u0628\u0627\u0644\u0639\u0631\u0628\u064a \u0639\u0634\u0627\u0646 \u0627\u0644\u0639\u0645\u064a\u0644 \u064a\u0642\u062f\u0631 \u064a\u0643\u062a\u0628\u0647 \u0628\u062f\u0648\u0646 \u0645\u0627 \u064a\u0637\u0644\u0628 \u0627\u0644\u0625\u0639\u0627\u062f\u0629.\n\n**\u064a\u062a\u0630\u0643\u0631 \u0627\u0644\u0639\u0645\u064a\u0644 \u0625\u0630\u0627 \u0627\u062a\u0635\u0644 \u0645\u0631\u0629 \u062b\u0627\u0646\u064a\u0629\u061f** \u0635\u0648\u062a \u0646\u062c\u062f\u064a \u064a\u062d\u062a\u0641\u0638 \u0628\u0630\u0627\u0643\u0631\u0629 \u0639\u0628\u0631 \u0627\u0644\u0645\u0643\u0627\u0644\u0645\u0627\u062a \u0644\u0643\u0644 \u0645\u0646\u0634\u0623\u0629: \u0627\u0644\u0639\u0645\u064a\u0644 \u0627\u0644\u0631\u0627\u062c\u0639 \u064a\u064f\u062d\u064a\u0651\u0649 \u0628\u0627\u0633\u0645\u0647\u060c \u0648\u062a\u0641\u0636\u064a\u0644\u0627\u062a\u0647 \u0648\u062d\u062c\u0648\u0632\u0627\u062a\u0647 \u0627\u0644\u0633\u0627\u0628\u0642\u0629 \u062a\u0643\u0648\u0646 \u062d\u0627\u0636\u0631\u0629 \u0642\u062f\u0627\u0645 \u0627\u0644\u0648\u0643\u064a\u0644 \u2014 \u0648\u0642\u062f\u0627\u0645 \u0645\u0648\u0638\u0641\u0643 \u0628\u0639\u062f \u0644\u0648 \u0627\u0633\u062a\u0644\u0645 \u0627\u0644\u0645\u0643\u0627\u0644\u0645\u0629.\n\n**\u0623\u0642\u062f\u0631 \u0623\u062c\u0645\u0639 \u0627\u0644\u0645\u0643\u0627\u0644\u0645\u0627\u062a \u0648\u0627\u0644\u0648\u0627\u062a\u0633\u0627\u0628 \u0648\u0627\u0644\u062a\u064a\u0644\u064a\u062c\u0631\u0627\u0645 \u0641\u064a \u0645\u0643\u0627\u0646 \u0648\u0627\u062d\u062f\u061f** \u0635\u0648\u062a \u0646\u062c\u062f\u064a \u064a\u062c\u0645\u0639 \u0627\u0644\u0645\u0643\u0627\u0644\u0645\u0627\u062a \u0648\u0648\u0627\u062a\u0633\u0627\u0628 \u0648\u062a\u064a\u0644\u064a\u062c\u0631\u0627\u0645 \u0648\u062f\u0631\u062f\u0634\u0629 \u0645\u0648\u0642\u0639\u0643 \u0641\u064a \u0635\u0646\u062f\u0648\u0642 \u0648\u0627\u0631\u062f \u0648\u0627\u062d\u062f \u0644\u0641\u0631\u064a\u0642\u0643\u060c \u0641\u0627\u0644\u0645\u0648\u0638\u0641 \u064a\u0634\u0648\u0641 \u0643\u0644 \u0645\u062d\u0627\u062f\u062b\u0627\u062a \u0627\u0644\u0639\u0645\u064a\u0644 \u0641\u064a \u0645\u0643\u0627\u0646 \u0648\u0627\u062d\u062f \u0628\u062f\u0644 \u0645\u0627 \u064a\u062a\u0646\u0642\u0644 \u0628\u064a\u0646 \u0623\u0631\u0628\u0639\u0629 \u062a\u0637\u0628\u064a\u0642\u0627\u062a \u2014 \u0648\u064a\u0642\u062f\u0631 \u064a\u062f\u062e\u0644 \u0639\u0644\u0649 \u0623\u064a \u0645\u062d\u0627\u062f\u062b\u0629 \u0628\u0623\u064a \u0644\u062d\u0638\u0629.\n\n**\u0648\u064a\u0646 \u062a\u0646\u062d\u0641\u0638 \u0628\u064a\u0627\u0646\u0627\u062a \u0645\u0643\u0627\u0644\u0645\u0627\u062a\u064a\u061f** \u0628\u064a\u0627\u0646\u0627\u062a\u0643 \u0641\u064a \u0635\u0648\u062a \u0646\u062c\u062f\u064a \u062a\u0646\u062d\u0641\u0638 \u0641\u064a \u0645\u0646\u0637\u0642\u0629 \u0627\u0644\u062e\u0644\u064a\u062c (\u0627\u0644\u062f\u0648\u062d\u0629) \u0639\u0644\u0649 Google Cloud\u060c \u0648\u0627\u0644\u062a\u0633\u062c\u064a\u0644\u0627\u062a \u062a\u0646\u062d\u0630\u0641 \u062a\u0644\u0642\u0627\u0626\u064a\u0627\u064b \u0628\u0639\u062f 90 \u064a\u0648\u0645\u0627\u064b\u060c \u0645\u0639 \u0625\u0641\u0635\u0627\u062d \u0643\u0627\u0645\u0644 \u0639\u0646 \u0623\u0645\u0627\u0643\u0646 \u0645\u0639\u0627\u0644\u062c\u0629 \u0627\u0644\u0635\u0648\u062a \u0648\u0627\u0644\u0630\u0643\u0627\u0621 \u0627\u0644\u0627\u0635\u0637\u0646\u0627\u0639\u064a \u0641\u064a \u0633\u064a\u0627\u0633\u0629 \u0627\u0644\u062e\u0635\u0648\u0635\u064a\u0629.\n\n**\u0645\u062a\u0648\u0627\u0641\u0642\u064a\u0646 \u0645\u0639 \u0646\u0638\u0627\u0645 \u062d\u0645\u0627\u064a\u0629 \u0627\u0644\u0628\u064a\u0627\u0646\u0627\u062a \u0627\u0644\u0634\u062e\u0635\u064a\u0629 (PDPL)\u061f** \u0635\u0648\u062a \u0646\u062c\u062f\u064a \u0645\u0635\u0645\u0651\u0645 \u0628\u0645\u0627 \u064a\u062a\u0648\u0627\u0641\u0642 \u0645\u0639 \u0646\u0638\u0627\u0645 \u062d\u0645\u0627\u064a\u0629 \u0627\u0644\u0628\u064a\u0627\u0646\u0627\u062a \u0627\u0644\u0634\u062e\u0635\u064a\u0629 \u0627\u0644\u0633\u0639\u0648\u062f\u064a (PDPL) \u2014 \u0628\u064a\u0627\u0646\u0627\u062a\u0643 \u0645\u062e\u0632\u0651\u0646\u0629 \u0641\u064a \u0645\u0646\u0637\u0642\u0629 \u0627\u0644\u062e\u0644\u064a\u062c\u060c \u0645\u0639 \u0625\u0641\u0635\u0627\u062d \u0643\u0627\u0645\u0644 \u0639\u0646 \u0623\u0645\u0627\u0643\u0646 \u0627\u0644\u0645\u0639\u0627\u0644\u062c\u0629. \u0648\u064a\u062f\u0639\u0645 \u0630\u0644\u0643 \u0633\u062c\u0644 \u062a\u062f\u0642\u064a\u0642 \u063a\u064a\u0631 \u0642\u0627\u0628\u0644 \u0644\u0644\u062a\u0639\u062f\u064a\u0644 \u0648\u0635\u0644\u0627\u062d\u064a\u0627\u062a \u0645\u062d\u062f\u062f\u0629 \u0644\u0643\u0644 \u0645\u0648\u0638\u0641. \u0648\u0645\u0627 \u0646\u0642\u0648\u0644 \u00ab\u0645\u0639\u062a\u0645\u062f\u00bb\u060c \u0648\u0645\u0627 \u0646\u0642\u0648\u0644 \u0625\u0646 \u0643\u0644 \u0627\u0644\u0645\u0639\u0627\u0644\u062c\u0629 \u062f\u0627\u062e\u0644 \u0627\u0644\u0633\u0639\u0648\u062f\u064a\u0629.\n\n**\u0647\u0644 \u0627\u0644\u0648\u0643\u064a\u0644 \u0627\u0644\u0635\u0648\u062a\u064a \u064a\u0639\u0648\u0651\u0636 \u0639\u0646 \u062a\u0648\u0637\u064a\u0646 \u0645\u0647\u0646 \u062e\u062f\u0645\u0629 \u0627\u0644\u0639\u0645\u0644\u0627\u0621\u061f** \u0635\u0648\u062a \u0646\u062c\u062f\u064a \u0645\u0627 \u064a\u0639\u0648\u0651\u0636 \u0639\u0646 \u0623\u064a \u0627\u0644\u062a\u0632\u0627\u0645 \u0646\u0638\u0627\u0645\u064a \u0628\u062a\u0648\u0637\u064a\u0646 \u0645\u0647\u0646 \u062e\u062f\u0645\u0629 \u0627\u0644\u0639\u0645\u0644\u0627\u0621 \u2014 \u0645\u0631\u062c\u0639 \u0645\u062a\u0637\u0644\u0628\u0627\u062a \u0627\u0644\u062a\u0648\u0637\u064a\u0646 \u0647\u0648 \u0648\u0632\u0627\u0631\u0629 \u0627\u0644\u0645\u0648\u0627\u0631\u062f \u0627\u0644\u0628\u0634\u0631\u064a\u0629 \u0648\u0627\u0644\u062a\u0646\u0645\u064a\u0629 \u0627\u0644\u0627\u062c\u062a\u0645\u0627\u0639\u064a\u0629\u060c \u0645\u0648 \u0646\u062d\u0646. \u0627\u0644\u0644\u064a \u064a\u0633\u0648\u064a\u0647 \u0635\u0648\u062a \u0646\u062c\u062f\u064a \u0625\u0646\u0647 \u064a\u0631\u062f \u0639\u0644\u0649 \u0627\u0644\u0645\u0643\u0627\u0644\u0645\u0627\u062a \u0627\u0644\u0631\u0648\u062a\u064a\u0646\u064a\u0629 \u0627\u0644\u0645\u062a\u0643\u0631\u0631\u0629 \u0648\u064a\u062e\u0644\u064a \u0641\u0631\u064a\u0642\u0643 \u0645\u062a\u0641\u0631\u063a \u0644\u0644\u0645\u0643\u0627\u0644\u0645\u0627\u062a \u0627\u0644\u0644\u064a \u062a\u062d\u062a\u0627\u062c \u0625\u0646\u0633\u0627\u0646 \u2014 \u0648\u0627\u0644\u0645\u0648\u0638\u0641 \u0627\u0644\u0644\u064a \u064a\u0633\u062a\u0644\u0645 \u0645\u0648\u0638\u0641\u0643 \u0623\u0646\u062a\u060c \u0648\u0627\u0644\u0642\u0648\u0627\u0639\u062f \u0642\u0648\u0627\u0639\u062f\u0643.\n\n**\u062a\u0633\u0648\u0648\u0646 \u0645\u0643\u0627\u0644\u0645\u0627\u062a \u0635\u0627\u062f\u0631\u0629\u061f** \u0625\u064a. \u0641\u0631\u064a\u0642\u0643 \u064a\u0637\u0644\u0639 \u0627\u0644\u0645\u0643\u0627\u0644\u0645\u0629 \u0645\u0646 \u0627\u0644\u0644\u0648\u062d\u0629 \u2014 \u064a\u062e\u062a\u0627\u0631 \u0627\u0644\u0639\u0645\u064a\u0644 \u0623\u0648 \u064a\u0643\u062a\u0628 \u0627\u0644\u0631\u0642\u0645 \u0648\u064a\u062e\u062a\u0627\u0631 \u0627\u0644\u0648\u0643\u064a\u0644 \u2014 \u0648\u0627\u0644\u0648\u0643\u064a\u0644 \u064a\u0645\u0633\u0643 \u0627\u0644\u062d\u0648\u0627\u0631\u060c \u0648\u062a\u0646\u0633\u062c\u0644 \u0648\u062a\u062a\u0643\u062a\u0628 \u0648\u064a\u0637\u0644\u0639 \u0644\u0647\u0627 \u0645\u0644\u062e\u0635 \u0645\u062b\u0644 \u0623\u064a \u0645\u0643\u0627\u0644\u0645\u0629. \u0627\u0644\u0645\u0643\u0627\u0644\u0645\u0629 \u064a\u0628\u062f\u0623\u0647\u0627 \u0645\u0648\u0638\u0641 \u0645\u0646 \u0639\u0646\u062f\u0643: \u0645\u0627 \u0641\u064a\u0647 \u0627\u062a\u0635\u0627\u0644 \u0622\u0644\u064a \u0639\u0644\u0649 \u0642\u0648\u0627\u0626\u0645 \u0623\u0631\u0642\u0627\u0645 \u0648\u0644\u0627 \u062d\u0645\u0644\u0627\u062a \u0627\u062a\u0635\u0627\u0644 \u0622\u0644\u064a\u0629.\n\n**\u0639\u0646\u062f\u0643\u0645 \u0631\u0642\u0645 \u0633\u0639\u0648\u062f\u064a \u0623\u062a\u0635\u0644 \u0639\u0644\u064a\u0647 \u0648\u0623\u062c\u0631\u0628\u061f** \u0635\u0648\u062a \u0646\u062c\u062f\u064a \u0645\u0627 \u064a\u0646\u0634\u0631 \u0631\u0642\u0645\u0627\u064b \u0633\u0639\u0648\u062f\u064a\u0627\u064b \u0644\u0644\u062a\u062c\u0631\u0628\u0629 \u0627\u0644\u064a\u0648\u0645\u060c \u0644\u0623\u0646 \u062a\u0641\u0639\u064a\u0644 \u0627\u0644\u0623\u0631\u0642\u0627\u0645 \u064a\u0645\u0631 \u0628\u0625\u062c\u0631\u0627\u0621\u0627\u062a \u0627\u0644\u062c\u0647\u0627\u062a \u0627\u0644\u062a\u0646\u0638\u064a\u0645\u064a\u0629 \u0644\u0644\u0627\u062a\u0635\u0627\u0644\u0627\u062a \u0648\u0645\u0627 \u0646\u0639\u0637\u064a \u0648\u0639\u062f\u0627\u064b \u0628\u062a\u0627\u0631\u064a\u062e \u0645\u0627 \u0646\u062a\u062d\u0643\u0645 \u0641\u064a\u0647. \u0627\u0644\u062a\u062c\u0631\u0628\u0629 \u062a\u0635\u064a\u0631 \u0641\u064a \u0627\u0644\u0639\u0631\u0636 \u0627\u0644\u062a\u0639\u0631\u064a\u0641\u064a: \u0646\u0634\u063a\u0651\u0644 \u0627\u0644\u0648\u0643\u064a\u0644 \u062d\u064a\u060c \u062a\u0633\u0645\u0639\u0647 \u0628\u0644\u0647\u062c\u062a\u0643\u060c \u0648\u062a\u0633\u0623\u0644\u0647 \u0627\u0644\u0644\u064a \u062a\u0628\u063a\u0649.\n\n**\u0643\u0645 \u062a\u0643\u0644\u0641\u0629 \u0627\u0644\u0648\u0643\u064a\u0644 \u0627\u0644\u0635\u0648\u062a\u064a \u0641\u064a \u0627\u0644\u0633\u0639\u0648\u062f\u064a\u0629\u061f** \u0623\u0633\u0639\u0627\u0631 \u0635\u0648\u062a \u0646\u062c\u062f\u064a \u0639\u0644\u0649 \u0642\u062f \u062d\u062c\u0645 \u0645\u0643\u0627\u0644\u0645\u0627\u062a\u0643 \u0648\u0642\u0646\u0648\u0627\u062a\u0643 \u2014 \u0645\u0627 \u0646\u0639\u0644\u0646 \u062c\u062f\u0648\u0644 \u0623\u0633\u0639\u0627\u0631 \u0639\u0627\u0645 \u0644\u0623\u0646\u0647 \u0645\u0627 \u064a\u0646\u0637\u0628\u0642 \u0639\u0644\u0649 \u0627\u0644\u0643\u0644 \u0628\u0625\u0646\u0635\u0627\u0641\u061b \u0628\u0639\u062f \u0627\u0644\u0639\u0631\u0636 \u0627\u0644\u062a\u0639\u0631\u064a\u0641\u064a \u0646\u0642\u064a\u0651\u0645 \u0646\u0634\u0627\u0637\u0643 \u0648\u0646\u0631\u0633\u0644 \u0644\u0643 \u0639\u0631\u0636 \u0633\u0639\u0631 \u0645\u0643\u062a\u0648\u0628 \u0648\u0648\u0627\u0636\u062d.\n\n**\u064a\u0646\u0627\u0633\u0628 \u0646\u0634\u0627\u0637\u064a\u061f** \u0635\u0648\u062a \u0646\u062c\u062f\u064a \u064a\u062c\u0647\u0632 \u0628\u0642\u0648\u0627\u0644\u0628 \u062c\u0627\u0647\u0632\u0629 \u0644\u0644\u0639\u064a\u0627\u062f\u0627\u062a \u0648\u0627\u0644\u0645\u0633\u062a\u0634\u0641\u064a\u0627\u062a \u0648\u0627\u0644\u0645\u0637\u0627\u0639\u0645 \u0648\u0627\u0644\u0641\u0646\u0627\u062f\u0642 \u0648\u0627\u0644\u0639\u0642\u0627\u0631\u0627\u062a \u0648\u0627\u0644\u062a\u062c\u0632\u0626\u0629 \u2014 \u0648\u0625\u0630\u0627 \u0646\u0634\u0627\u0637\u0643 \u0634\u064a \u062b\u0627\u0646\u064a\u060c \u0646\u062c\u0647\u0632 \u0644\u0643 \u0648\u0643\u064a\u0644\u0643 \u0639\u0644\u0649 \u0645\u0642\u0627\u0633 \u0634\u063a\u0644\u0643.\n\n**\u0643\u064a\u0641 \u0623\u0628\u062f\u0623\u061f** \u062a\u0628\u062f\u0623 \u0645\u0639 \u0635\u0648\u062a \u0646\u062c\u062f\u064a \u0628\u062d\u062c\u0632 \u0639\u0631\u0636 \u062a\u0639\u0631\u064a\u0641\u064a \u2014 \u0641\u0631\u064a\u0642\u0646\u0627 \u064a\u062c\u0647\u0632 \u0644\u0643 \u0643\u0644 \u0634\u064a: \u0627\u0644\u0648\u0643\u064a\u0644\u060c \u0648\u0642\u0627\u0639\u062f\u0629 \u0627\u0644\u0645\u0639\u0631\u0641\u0629\u060c \u0648\u0642\u0648\u0627\u0639\u062f \u0627\u0644\u062a\u0635\u0639\u064a\u062f\u060c \u0648\u0645\u0627 \u0641\u064a \u062a\u0633\u062c\u064a\u0644 \u0630\u0627\u062a\u064a.\n\n## \u0627\u0644\u0635\u0641\u062d\u0627\u062a \u2014 \u0627\u0644\u0639\u0631\u0628\u064a\u0629 (\u0627\u0644\u0623\u0633\u0627\u0633\u064a\u0629)\n\n- [\u0627\u0644\u0631\u0626\u064a\u0633\u064a\u0629](https://sautnajdi.ai/): \u0648\u0634 \u0647\u0648 \u0635\u0648\u062a \u0646\u062c\u062f\u064a\u060c \u0648\u0627\u0644\u0645\u0634\u0643\u0644\u0629 \u0627\u0644\u0644\u064a \u064a\u062d\u0644\u0647\u0627\u060c \u0648\u0627\u0644\u0646\u0645\u0648\u0630\u062c \u0627\u0644\u0647\u062c\u064a\u0646\n- [\u0643\u064a\u0641 \u064a\u0634\u062a\u063a\u0644](https://sautnajdi.ai/how-it-works): \u0631\u062d\u0644\u0629 \u0645\u0643\u0627\u0644\u0645\u0629 \u0648\u062d\u062f\u0629 \u0628\u0633\u0628\u0639 \u062e\u0637\u0648\u0627\u062a \u2014 \u0645\u0646 \u0623\u0648\u0644 \u0631\u0646\u0629 \u0625\u0644\u0649 \u0622\u062e\u0631 \u0633\u0637\u0631 \u0641\u064a \u0627\u0644\u0633\u062c\u0644\n- [\u0627\u0644\u062a\u0635\u0639\u064a\u062f \u0644\u0644\u0645\u0648\u0638\u0641 \u0627\u0644\u0628\u0634\u0631\u064a](https://sautnajdi.ai/product/human-handoff): \u0642\u0648\u0627\u0639\u062f \u0627\u0644\u062a\u0635\u0639\u064a\u062f\u060c \u0648\u0627\u0644\u0627\u0633\u062a\u0645\u0627\u0639 \u0648\u0627\u0644\u0647\u0645\u0633 \u0648\u0627\u0644\u0627\u0633\u062a\u0644\u0627\u0645 \u0627\u0644\u0645\u0628\u0627\u0634\u0631\u060c \u0648\u0627\u0644\u0633\u064a\u0627\u0642 \u0627\u0644\u0645\u0646\u0642\u0648\u0644\u060c \u0648\u0637\u0644\u0628\u0627\u062a \u0627\u0644\u0627\u062a\u0635\u0627\u0644 \u0628\u0631\u0627 \u0627\u0644\u062f\u0648\u0627\u0645\n- [\u0627\u0644\u0623\u0645\u0627\u0646 \u0648\u0627\u0644\u0628\u064a\u0627\u0646\u0627\u062a](https://sautnajdi.ai/security): \u0627\u0644\u062a\u0648\u0627\u0641\u0642 \u0645\u0639 PDPL\u060c \u0648\u0645\u0646\u0637\u0642\u0629 \u0627\u0644\u062a\u062e\u0632\u064a\u0646\u060c \u0648\u0627\u0644\u0625\u0641\u0635\u0627\u062d \u0639\u0646 \u0627\u0644\u0645\u0639\u0627\u0644\u062c\u0629\u060c \u0648\u0633\u062c\u0644 \u0627\u0644\u062a\u062f\u0642\u064a\u0642\u060c \u0648\u0627\u0644\u062a\u062d\u0643\u0645 \u0641\u064a \u0627\u0644\u0648\u0635\u0648\u0644\n- [\u0627\u0644\u0623\u0633\u0626\u0644\u0629 \u0627\u0644\u0634\u0627\u0626\u0639\u0629](https://sautnajdi.ai/faq): \u0643\u0644 \u0627\u0644\u0623\u0633\u0626\u0644\u0629 \u0645\u0631\u062a\u0628\u0629 \u0628\u0645\u062c\u0645\u0648\u0639\u0627\u062a\n- [\u0627\u062d\u062c\u0632 \u0639\u0631\u0636\u0627\u064b](https://sautnajdi.ai/demo): \u0639\u0631\u0636 \u062a\u0639\u0631\u064a\u0641\u064a 30 \u062f\u0642\u064a\u0642\u0629\u060c \u0648\u0643\u064a\u0641 \u064a\u064f\u062d\u062f\u062f \u0627\u0644\u0633\u0639\u0631\n- [\u062a\u0648\u0627\u0635\u0644 \u0645\u0639\u0646\u0627](https://sautnajdi.ai/contact): \u0627\u0644\u0625\u064a\u0645\u064a\u0644 \u0648\u0645\u0643\u0627\u0644\u0645\u0629 \u0633\u0631\u064a\u0639\u0629 15 \u062f\u0642\u064a\u0642\u0629\n- [\u0645\u0646 \u0646\u062d\u0646](https://sautnajdi.ai/about): \u0645\u064a\u0646 \u0648\u0631\u0627\u0621 \u0627\u0644\u0645\u0646\u062a\u062c\u060c \u0648\u0644\u064a\u0647 \u0647\u062c\u064a\u0646\u060c \u0648\u0648\u0634 \u0627\u0644\u0644\u064a \u0646\u0631\u0641\u0636 \u0646\u062f\u0651\u0639\u064a\u0647\n- [\u0633\u064a\u0627\u0633\u0629 \u0627\u0644\u062e\u0635\u0648\u0635\u064a\u0629](https://sautnajdi.ai/privacy)\n- [\u0634\u0631\u0648\u0637 \u0627\u0644\u062e\u062f\u0645\u0629](https://sautnajdi.ai/terms)\n- [\u0627\u062a\u0641\u0627\u0642\u064a\u0629 \u0645\u0639\u0627\u0644\u062c\u0629 \u0627\u0644\u0628\u064a\u0627\u0646\u0627\u062a](https://sautnajdi.ai/dpa)\n\n## \u0627\u0644\u0645\u062f\u0648\u0646\u0629\n\n\u0645\u0642\u0627\u0644\u0627\u062a \u062a\u0648\u0636\u064a\u062d\u064a\u0629 \u0645\u0648\u062c\u0651\u0647\u0629 \u0644\u0645\u0646 \u064a\u0642\u064a\u0651\u0645 \u062d\u0644\u0627\u064b \u0641\u0639\u0644\u064a\u0627\u064b. \u0643\u0644 \u0645\u0642\u0627\u0644 \u0645\u0648\u062c\u0648\u062f \u0628\u0627\u0644\u0644\u063a\u062a\u064a\u0646 \u0639\u0644\u0649 \u0646\u0641\u0633\n\u0627\u0644\u0645\u0633\u0627\u0631 \u2014 \u0627\u0644\u0639\u0631\u0628\u064a\u0629 \u0639\u0644\u0649 \u200e/blog/<slug>\u200e \u0648\u0627\u0644\u0625\u0646\u062c\u0644\u064a\u0632\u064a\u0629 \u0639\u0644\u0649 \u200e/en/blog/<slug>\u200e. \u0645\u0642\u0627\u0644 PDPL\n\u062a\u0648\u0636\u064a\u062d\u064a \u0648\u0644\u064a\u0633 \u0627\u0633\u062a\u0634\u0627\u0631\u0629 \u0642\u0627\u0646\u0648\u0646\u064a\u0629.\n\n";
